import EventEmitter from "events";
const partialStateSyncEmitter = new EventEmitter();
const prefabStateSyncEmitter = new EventEmitter();
const layoutSyncEmitter = new EventEmitter();
partialStateSyncEmitter.setMaxListeners(50);
prefabStateSyncEmitter.setMaxListeners(50);
layoutSyncEmitter.setMaxListeners(50);
const EVENTEMITTER = {
  LAYOUT_STATE_REFRESH: "layout-state-refresh",
  PARTIAL_STATE_SYNC: "partial-state-sync",
  PREFAB_STATE_SYNC: "prefab-state-sync"
};
const EVENTEMITTER_METHODS = {
  PREFAB_STATE_SYNC_ON: (name = "", callback) => {
    return prefabStateSyncEmitter.on(
      EVENTEMITTER.PREFAB_STATE_SYNC + (name ? "_" + name : ""),
      callback
    );
  },
  PREFAB_STATE_SYNC_OFF: (name = "", callback) => {
    return prefabStateSyncEmitter.off(
      EVENTEMITTER.PREFAB_STATE_SYNC + (name ? "_" + name : ""),
      callback
    );
  },
  PREFAB_STATE_SYNC_EMIT: (name = "", data) => {
    return prefabStateSyncEmitter.emit(
      EVENTEMITTER.PREFAB_STATE_SYNC + (name ? "_" + name : ""),
      data
    );
  },
  PARTIAL_STATE_SYNC_ON: (callback) => {
    return partialStateSyncEmitter.on(EVENTEMITTER.PARTIAL_STATE_SYNC, callback);
  },
  PARTIAL_STATE_SYNC_OFF: (callback) => {
    return partialStateSyncEmitter.off(EVENTEMITTER.PARTIAL_STATE_SYNC, callback);
  },
  PARTIAL_STATE_SYNC_EMIT: (data) => {
    return partialStateSyncEmitter.emit(EVENTEMITTER.PARTIAL_STATE_SYNC, data);
  },
  LAYOUT_STATE_REFRESH_ON: (callback) => {
    return layoutSyncEmitter.on(EVENTEMITTER.LAYOUT_STATE_REFRESH, callback);
  },
  LAYOUT_STATE_REFRESH_OFF: (callback) => {
    return layoutSyncEmitter.off(EVENTEMITTER.LAYOUT_STATE_REFRESH, callback);
  },
  LAYOUT_STATE_REFRESH_EMIT: (data) => {
    return layoutSyncEmitter.emit(EVENTEMITTER.LAYOUT_STATE_REFRESH, data);
  }
};
export {
  EVENTEMITTER_METHODS
};
